create table replenishment_requests (acceptance_consumed bit not null, quantity float(53) not null, unit_price float(53) not null, version integer not null, created_at datetime(6) not null, customer_account_id bigint, fuel_product_id bigint not null, id bigint not null auto_increment, order_id bigint, organization_id bigint not null, provider_id bigint not null, tank_id bigint, updated_at datetime(6) not null, episode_key varchar(120), rejection_reason varchar(240), unit varchar(20) not null, source VARCHAR(20) not null, status VARCHAR(20) not null, primary key (id)) engine=InnoDB;
alter table replenishment_requests add constraint uk_replenishment_requests_episode_key unique (episode_key);
